UPDATE agent_tasks SET status=#{status},goal=#{goal},source_name=#{sourceName},answer=#{answer},question=#{question},error=#{error},retryable=#{retryable},statistics_json=#{statisticsJson},draft_json=#{draftJson},task_token=#{taskToken},pending_input=#{pendingInput},plan_id=#{planId},report_id=#{reportId},confirmed_version=#{confirmedVersion},operation_id=#{operationId},
  confirmed_at=#{confirmedAt},feedback=#{feedback},feedback_at=IF(#{feedback} IS NULL,NULL,feedback_at),
  updated_at=CURRENT_TIMESTAMP(6) WHERE id=#{id}

mapper.select:
WITH RECURSIVE related AS (
  SELECT id FROM agent_tasks WHERE user_id=#{userId} AND parent_task_id=#{id}
  UNION ALL
  SELECT t.id FROM agent_tasks t JOIN related r ON t.parent_task_id=r.id WHERE t.user_id=#{userId}
)
SELECT t.* FROM agent_tasks t JOIN related r ON t.id=r.id
WHERE t.user_id=#{userId} ORDER BY t.id FOR UPDATE

SELECT * FROM agent_tasks WHERE user_id=#{userId} AND kind='COMBINED'
  AND start_date <= #{end} AND end_date >= #{start}
ORDER BY id FOR UPDATE
